void process_display_param(inout DisplayParameters parameters, float lifetime) {
	// Compile-time add textures.
	parameters.scale *= texture(scale_curve, vec2(lifetime)).rgb;
	parameters.color *= texture(color_ramp, vec2(lifetime));
	parameters.color = rotate_hue(parameters.color, parameters.hue_rotation);
}

var direction: float = signf(x - previous_x)
while _since_step >= stride_px:
	_since_step -= stride_px
	_spawn(RATIO_STRIDE, -direction * _since_step)

## Distinct effect instances that have existed during this condition. The
## drivers spawn and free a scene per event, and THAT -- not the particle
## process, which never runs headless -- is what a non-zero difference here
## would be made of.
func _count_instances(node: Node) -> void:
	for child in node.get_children():
		if child.has_method("fire") and child.has_method("lifetime"):
			_instances_seen[child.get_instance_id()] = true
